alter table ecology.ssr_reference_addresses add column if not exists w3w_validation_status text not null default 'historical_reference_unverified' check (w3w_validation_status in ('historical_reference_unverified','api_validated','api_rejected','api_mismatch','not_applicable')); alter table ecology.ssr_reference_addresses add column if not exists w3w_validated_at timestamptz; alter table ecology.ssr_reference_addresses add column if not exists w3w_validation_evidence jsonb not null default '{}'::jsonb; update ecology.ssr_reference_addresses set w3w_validation_status='historical_reference_unverified', roster_mapping_status='unmapped', updated_at=now() where surface_anchor is not null and w3w_validation_status <> 'api_validated'; create table if not exists ecology.ssr_w3w_validation_log (id uuid primary key default gen_random_uuid(), subject_type text not null check(subject_type in ('coordinate_candidate','historical_reference','anchor_tile')), subject_id text not null, request_mode text not null check(request_mode in ('coordinates','words')), input_latitude double precision, input_longitude double precision, input_words text, resolved_words text, resolved_latitude double precision, resolved_longitude double precision, provider text not null default 'what3words', provider_endpoint text not null, validation_status text not null check(validation_status in ('pending','validated','rejected','mismatch','error')), response_metadata jsonb not null default '{}'::jsonb, validated_at timestamptz not null default now(), unique(subject_type,subject_id,request_mode)); alter table ecology.ssr_w3w_validation_log enable row level security; drop policy if exists ssr_w3w_validation_log_service_role_all on ecology.ssr_w3w_validation_log; create policy ssr_w3w_validation_log_service_role_all on ecology.ssr_w3w_validation_log for all to service_role using (true) with check (true); create or replace view ecology.ssr_w3w_validation_dashboard as select (select count(*) from ecology.ssr_anchor_candidate_registry where latitude is not null and longitude is not null) coordinate_candidates, (select count(*) from ecology.ssr_anchor_candidate_registry where w3w_address is not null) coordinate_candidates_with_w3w, (select count(*) from ecology.ssr_reference_addresses) historical_references, (select count(*) from ecology.ssr_reference_addresses where w3w_validation_status='api_validated') historical_references_api_validated, (select count(*) from ecology.ssr_reference_addresses where w3w_validation_status='historical_reference_unverified') historical_references_unverified, (select count(*) from public.anchor_tiles) authoritative_anchor_tiles, (select count(*) from ecology.ssr_w3w_validation_log where validation_status='validated') validated_api_transactions;
